<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useAuthStore } from '../stores/auth'
import { useNotifications, type Notice } from '../stores/notifications'
import { teacherApi } from '../api/http'
import NotificationItem from '../components/notifications/NotificationItem.vue'
import NotificationDetail from '../components/notifications/NotificationDetail.vue'
const store=useNotifications(), auth=useAuthStore()
const items=ref<Notice[]>([]), total=ref(0), page=ref(1), unread=ref(false), loading=ref(false), error=ref('')
const detail=ref<InstanceType<typeof NotificationDetail>>()
const canPublish=computed(()=>['admin','teacher'].includes(auth.user?.role||''))
const scope=ref('class'),target=ref<number>(),title=ref(''),content=ref(''),type=ref('announcement'),sending=ref(false),result=ref('')
let requestKey=crypto.randomUUID(), sentPayload=''
const scopes=computed(()=>auth.user?.role==='admin'?[['students','全体学生'],['teachers','全体教师'],['class','指定班级'],['course','指定课程'],['student','指定学生'],['teacher','指定教师']]:[['class','本人班级'],['course','本人课程'],['student','本人班级学生']])
async function load(){loading.value=true;error.value='';try{const data=await store.list(page.value,20,unread.value);items.value=data.items;total.value=data.total}catch{items.value=[];total.value=0;error.value='消息读取失败，请重试'}finally{loading.value=false}}
async function all(){try{await store.readAll();await load()}catch{error.value='已读状态更新失败，请重试'}}
async function send(){sending.value=true;result.value='';const payload={scope:scope.value,target_id:['students','teachers'].includes(scope.value)?null:target.value,title:title.value,content:content.value,type:type.value};const signature=JSON.stringify(payload);if(signature!==sentPayload){requestKey=crypto.randomUUID();sentPayload=signature}try{const {data}=await teacherApi.post('/learning/notifications/publish',{...payload,request_key:requestKey});result.value=`已发送给 ${data.data.recipient_count} 位接收人`;title.value='';content.value='';requestKey=crypto.randomUUID();await load()}catch(e:any){result.value=e?.response?.data?.detail || '发送失败，可重试；相同请求不会重复投递'}finally{sending.value=false}}
watch([page,unread],load);watch(()=>store.revision,load);onMounted(load)
</script>
<template><div class="notification-center"><header><h1>消息中心</h1><p>通知按当前账号与课程权限展示</p><el-switch v-model="unread" active-text="仅看未读" @change="page=1"/><el-button @click="all">全部标为已读</el-button><el-button @click="load">刷新</el-button></header><el-alert v-if="error" :title="error" type="error"/><p v-if="loading" role="status">正在加载…</p><NotificationItem v-for="item in items" :key="item.id" :item="item" @select="detail?.show($event)"/><el-empty v-if="!loading&&!error&&!items.length" description="暂无消息"/><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total"/><NotificationDetail ref="detail"/><section v-if="canPublish" class="publication"><h2>发布通知</h2><p>接收人由服务端按有效账号和班级、课程关系重新解析。单次最多5000人。</p><el-form label-position="top" @submit.prevent="send"><el-form-item label="接收范围"><el-select v-model="scope"><el-option v-for="item in scopes" :key="item[0]" :label="item[1]" :value="item[0]"/></el-select></el-form-item><el-form-item v-if="!['students','teachers'].includes(scope)" label="班级 / 课程 / 用户 ID"><el-input-number v-model="target" :min="1"/></el-form-item><el-form-item label="通知类型"><el-select v-model="type"><el-option label="公告" value="announcement"/><el-option label="系统维护" value="maintenance"/><el-option label="账号通知" value="account"/><el-option label="课程通知" value="course"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="title" maxlength="160" required/></el-form-item><el-form-item label="正文"><el-input v-model="content" type="textarea" :rows="5" maxlength="10000" required/></el-form-item><el-button type="primary" native-type="submit" :loading="sending" :disabled="!title.trim()||!content.trim()">发布通知</el-button><p role="status">{{ result }}</p></el-form></section></div></template>
<style scoped>.notification-center{max-width:900px;margin:0 auto}.notification-center header{margin-bottom:20px}.notification-center header p,.publication p{color:var(--muted);line-height:1.7}.notification-center header .el-button{margin-left:12px}.publication{margin-top:28px;padding:22px;border:1px solid var(--line);border-radius:16px;background:var(--panel)}.el-pagination{margin-top:18px;max-width:100%;overflow:auto}</style>
